import{_ as s,C as l,o as d,c as u,a2 as a,b as c,w as e,a as i,E as r,a3 as n}from"./chunks/framework.BaXgE4DV.js";const b=JSON.parse('{"title":"알림","description":"","frontmatter":{},"headers":[],"relativePath":"features/notifications.md","filePath":"features/notifications.md","lastUpdated":1791510387000}'),E={name:"features/notifications.md"};function h(A,t,B,C,p,m){const o=l("Mermaid");return d(),u("div",null,[t[2]||(t[2]=a('<h1 id="알림" tabindex="-1">알림 <a class="header-anchor" href="#알림" aria-label="Permalink to &quot;알림&quot;">​</a></h1><p>푸시는 Firebase Cloud Messaging(FCM)으로 보냅니다. 서버는 Cloud Functions 트리거와 스케줄러, 웹 클라이언트는 서비스 워커(<code>public/firebase-messaging-sw.js</code>)와 <code>src/lib/pushNotifications.js</code>가 담당합니다. iOS·Android 앱은 네이티브 푸시(<code>src/lib/native/push.js</code>)를 쓰고, 매일 알림은 서버 푸시 대신 휴대폰이 직접 띄웁니다. → <a href="#app">앱 (iOS·Android)</a></p><h2 id="알림-종류" tabindex="-1">알림 종류 <a class="header-anchor" href="#알림-종류" aria-label="Permalink to &quot;알림 종류&quot;">​</a></h2><table tabindex="0"><thead><tr><th>종류 (<code>data.type</code>)</th><th>언제</th><th>받는 사람</th><th>끄는 설정</th><th>클릭 시</th><th>중복 방지 키</th></tr></thead><tbody><tr><td><code>circle_post</code></td><td>Circle에 새 글 (<code>onGratitudeCreated</code>)</td><td>작성자를 뺀 Circle 멤버 (작성자를 차단한 멤버 제외). 자동 숨김된 글은 보내지 않음</td><td><code>circlePostNotice</code></td><td><code>/gratitude/{id}</code></td><td><code>circle_post_{gratitudeId}</code></td></tr><tr><td><code>reaction</code></td><td>내 글에 새 리액션 (<code>onReactionUpdated</code>)</td><td>글 작성자 (본인 리액션, 작성자가 차단한 사람의 리액션 제외)</td><td><code>reactionNotice</code></td><td><code>/gratitude/{id}</code></td><td><code>reaction_{gratitudeId}_{reactorUid}_{emoji}</code></td></tr><tr><td><code>daily_reminder</code></td><td>설정한 시각 (<code>sendDailyReminder</code>). 앱은 휴대폰 자체 알림</td><td>오늘 아직 쓰지 않은 사용자 (앱이 로컬 알림을 맡은 사용자 제외)</td><td><code>dailyReminder</code></td><td><code>/write</code></td><td><code>daily_reminder_{uid}_{YYYYMMDD}_{HHMM}</code></td></tr><tr><td><code>question_selected</code></td><td>제안한 질문이 처음 선정됨 (<code>reviewQuestion</code>)</td><td>제안자</td><td>없음</td><td><code>/mypage#questions</code></td><td><code>question_selected_{questionId}</code> (+ 처음 선정일 때만 보냄)</td></tr><tr><td><code>report</code></td><td>새 신고 접수 (<code>onReportCreated</code>)</td><td>운영자(<code>isAdmin</code>) 전원</td><td>없음</td><td><code>/admin?tab=reports</code></td><td><code>report_{reportId}</code> (+ 대상의 첫 열린 신고일 때만, 차단 신고는 보내지 않음)</td></tr></tbody></table><p>알림 문구 예:</p><ul><li>Circle 새 글: &quot;{공개 이름}님이 감사를 기록했어요&quot; / 본문은 글 제목</li><li>리액션: &quot;{공개 이름}님이 공감했어요 ❤️&quot; / 본문은 글 제목</li><li>매일 알림: &quot;오늘의 감사를 기록해보세요 🙏&quot; / &quot;하루를 돌아보며 감사한 순간을 적어볼까요?&quot;</li><li>질문 선정: &quot;제안한 질문이 선정됐어요 🎉&quot; / 본문은 질문 문구 → <a href="#question-selected">질문 선정 알림</a></li><li>신고(운영자): &quot;새 신고가 접수됐어요&quot; / &quot;감사 글 · 욕설·괴롭힘. 24시간 안에 확인해주세요&quot;. 잠금 화면에 보이므로 신고된 내용과 이름은 넣지 않음 → <a href="/grato-docs/features/safety#report-trigger">신고</a></li></ul><p>차단은 그 사람 <strong>때문에</strong> 오는 알림(새 글, 리액션)을 막습니다. 차단 여부는 보내기 전에 받는 사람의 차단 목록(<code>users/{uid}/blocks</code>)을 읽어 확인합니다. → <a href="/grato-docs/features/safety#block">차단</a></p><h2 id="알림-설정" tabindex="-1">알림 설정 <a class="header-anchor" href="#알림-설정" aria-label="Permalink to &quot;알림 설정&quot;">​</a></h2><p><code>users/{uid}.notificationSettings</code> (MyPage에서 변경):</p><table tabindex="0"><thead><tr><th>키</th><th>기본값</th><th>비고</th></tr></thead><tbody><tr><td><code>dailyReminder</code></td><td>true</td><td>서버는 <code>== true</code>인 사용자만 조회. 필드가 없으면 보내지 않음</td></tr><tr><td><code>dailyReminderHour</code></td><td>21</td><td>0~23, KST 시</td></tr><tr><td><code>dailyReminderMinute</code></td><td>0</td><td>0·15·30·45, KST 분. 없으면 0(분 단위 도입 전 설정)</td></tr><tr><td><code>reactionNotice</code></td><td>true</td><td>필드가 없으면 켜진 것으로 취급</td></tr><tr><td><code>circlePostNotice</code></td><td>true</td><td>필드가 없으면 켜진 것으로 취급</td></tr><tr><td><code>dailyReminderChannel</code></td><td>없음</td><td>앱만 씀. <code>&#39;local&#39;</code>이면 그 사용자의 휴대폰 앱이 매일 알림을 로컬 알림으로 띄우는 중 → 서버가 보내지 않음. 알림을 끄거나 로그아웃하면 <code>null</code></td></tr><tr><td><code>dailyReminderLocalAt</code></td><td>없음</td><td>앱이 <code>&#39;local&#39;</code>을 쓸 때의 서버 시각. 하루에 한 번까지 갱신, 14일이 지나면 서버가 <code>&#39;local&#39;</code>을 무시</td></tr></tbody></table><p>설정은 <code>notificationSettings.&lt;키&gt;</code> 점 표기법으로 한 키씩 갱신해, 클라이언트가 모르는 새 키를 지우지 않습니다.</p><h2 id="message-shape" tabindex="-1">메시지 모양: 웹은 데이터 전용, 앱은 notification <a class="header-anchor" href="#message-shape" aria-label="Permalink to &quot;메시지 모양: 웹은 데이터 전용, 앱은 notification {#message-shape}&quot;">​</a></h2><p><code>utils/messaging.ts</code>의 <code>sendToUser</code>는 사용자의 토큰마다 <code>buildPushMessage</code>로 메시지를 만듭니다. 토큰 문서의 <code>platform</code>(<code>web</code> · <code>ios</code> · <code>android</code>, 없거나 모르는 값은 <code>web</code>)에 따라 모양이 다릅니다. 어느 쪽이든 <code>data</code>에 <code>title</code>, <code>body</code>, <code>type</code>, <code>gratitudeId</code> 등이 들어갑니다.</p><table tabindex="0"><thead><tr><th>플랫폼</th><th>메시지</th><th>이유</th></tr></thead><tbody><tr><td><code>web</code></td><td><strong>데이터 전용</strong> (최상위 <code>notification</code> 키 없음)</td><td><code>notification</code> 키가 있으면 브라우저가 알림을 자동으로 띄우고 서비스 워커도 띄워 <strong>두 번</strong> 보임. 표시는 서비스 워커(백그라운드)와 페이지(포그라운드)가 전적으로 맡음</td></tr><tr><td><code>ios</code>, <code>android</code></td><td><code>notification</code>(제목·본문) + 같은 <code>data</code>, APNs 기본 소리, Android 채널 <code>grato_push</code>·높은 우선순위</td><td>iOS는 데이터 전용 메시지를 시스템 알림으로 보여 주지 않고, Android도 백그라운드에서 데이터 전용 메시지를 표시하지 않음. 앱이 꺼져 있어도 OS가 표시</td></tr></tbody></table><h2 id="발송-흐름" tabindex="-1">발송 흐름 <a class="header-anchor" href="#발송-흐름" aria-label="Permalink to &quot;발송 흐름&quot;">​</a></h2>',15)),(d(),c(n,null,{default:e(()=>[r(o,{id:"mermaid-319",class:"mermaid",graph:"sequenceDiagram%0A%20%20participant%20T%20as%20%ED%8A%B8%EB%A6%AC%EA%B1%B0%20%2F%20%EC%8A%A4%EC%BC%80%EC%A4%84%EB%9F%AC%0A%20%20participant%20L%20as%20notificationLogs%0A%20%20participant%20F%20as%20Firestore%0A%20%20participant%20M%20as%20FCM%0A%20%20participant%20D%20as%20%EA%B8%B0%EA%B8%B0%0A%20%20T-%3E%3EL%3A%20%EC%9D%B4%EB%B2%A4%ED%8A%B8%20ID%20%EC%B2%98%EB%A6%AC%20%EC%97%AC%EB%B6%80%20%ED%99%95%EC%9D%B8%0A%20%20alt%20%EC%9D%B4%EB%AF%B8%20%EC%B2%98%EB%A6%AC%EB%90%A8%0A%20%20%20%20T--%3E%3ET%3A%20%EA%B1%B4%EB%84%88%EB%9C%80%0A%20%20else%20%EC%B2%98%EC%9D%8C%0A%20%20%20%20T-%3E%3EF%3A%20%EB%B0%9B%EB%8A%94%20%EC%82%AC%EB%9E%8C%20%EC%84%A4%EC%A0%95%20%C2%B7%20pushTokens%20%EC%A1%B0%ED%9A%8C%0A%20%20%20%20T-%3E%3EM%3A%20%ED%86%A0%ED%81%B0%EB%A7%88%EB%8B%A4%20%ED%94%8C%EB%9E%AB%ED%8F%BC%EC%97%90%20%EB%A7%9E%EB%8A%94%20%EB%A9%94%EC%8B%9C%EC%A7%80%20(%EB%B3%91%EB%A0%AC)%0A%20%20%20%20M--%3E%3ED%3A%20%EC%84%9C%EB%B9%84%EC%8A%A4%20%EC%9B%8C%EC%BB%A4(%EC%9B%B9)%20%EB%98%90%EB%8A%94%20OS(%EC%95%B1)%EA%B0%80%20%ED%91%9C%EC%8B%9C%0A%20%20%20%20M--%3E%3ET%3A%20%EB%AC%B4%ED%9A%A8%20%ED%86%A0%ED%81%B0%20%EC%98%A4%EB%A5%98%EB%A9%B4%20%ED%86%A0%ED%81%B0%20%EB%AC%B8%EC%84%9C%20%EC%82%AD%EC%A0%9C%0A%20%20%20%20T-%3E%3EL%3A%20processed%20%EA%B8%B0%EB%A1%9D%20(30%EC%9D%BC%20TTL)%0A%20%20end%0A"})]),fallback:e(()=>[...t[0]||(t[0]=[i(" Loading... ",-1)])]),_:1})),t[3]||(t[3]=a('<ul><li>토큰이 없는 사용자는 오류가 아니라 건너뜁니다.</li><li><code>messaging/invalid-registration-token</code>, <code>messaging/registration-token-not-registered</code> 오류가 나면 그 토큰 문서를 지웁니다.</li><li>기록은 발송 <strong>뒤에</strong> 남기므로, 발송 직후 함수가 죽으면 재시도 때 한 번 더 갈 수 있습니다(최선 노력 방식의 중복 방지).</li></ul><h2 id="웹-클라이언트" tabindex="-1">웹 클라이언트 <a class="header-anchor" href="#웹-클라이언트" aria-label="Permalink to &quot;웹 클라이언트&quot;">​</a></h2><p>앱의 차이는 <a href="#app">아래</a>에 있습니다.</p><h3 id="토큰-등록" tabindex="-1">토큰 등록 <a class="header-anchor" href="#토큰-등록" aria-label="Permalink to &quot;토큰 등록&quot;">​</a></h3><p><code>pushTokens/{uid}/tokens/{token}</code>에 <code>{token, platform: &#39;web&#39;, userAgent, createdAt}</code>을 저장합니다(앱은 <code>{token, platform: &#39;ios&#39; | &#39;android&#39;, createdAt}</code> → <a href="#app">앱</a>). 토큰 문자열을 문서 ID로 써서 같은 기기를 다시 등록해도 문서가 하나입니다.</p><ul><li>로그인할 때마다 <code>registerPushToken(uid)</code>를 부르지만, 권한이 이미 <code>granted</code>일 때만 토큰을 저장합니다. <strong>권한 창을 자동으로 띄우지 않습니다.</strong></li><li>권한 요청은 사용자가 버튼을 눌렀을 때만 합니다(<code>enablePushNotifications</code>). 브라우저는 사용자 동작 없는 권한 요청을 막거나 사용자가 거부하기 쉬우므로, 거부되면 다시 물을 수 없기 때문입니다.</li></ul><h3 id="권한-ux" tabindex="-1">권한 UX <a class="header-anchor" href="#권한-ux" aria-label="Permalink to &quot;권한 UX&quot;">​</a></h3><table tabindex="0"><thead><tr><th>위치</th><th>동작</th></tr></thead><tbody><tr><td>홈 <code>PushPromptCard</code></td><td>권한이 <code>default</code>이고 FCM을 지원하는 브라우저에서만 표시. &quot;알림 받기&quot;를 누르면 권한 요청. 닫으면 <code>localStorage</code>의 <code>push-prompt-dismissed</code>에 기억</td></tr><tr><td>MyPage 알림 설정</td><td>기기의 푸시 상태(지원 여부, 권한, 등록된 토큰 수)를 보여 주고 켜기 버튼 제공. 종류별 토글과 매일 알림 시각 선택</td></tr></tbody></table><h3 id="표시" tabindex="-1">표시 <a class="header-anchor" href="#표시" aria-label="Permalink to &quot;표시&quot;">​</a></h3><ul><li><strong>백그라운드</strong>: 서비스 워커의 <code>onBackgroundMessage</code>가 <code>data.title</code>/<code>data.body</code>로 알림을 띄웁니다. 클릭하면 <code>data.type</code>에 맞는 경로(위 표의 &quot;클릭 시&quot;)로, 열린 창이 있으면 그 창을 이동·포커스하고, 없으면 새 창을 엽니다.</li><li><strong>포그라운드</strong>: <code>App.jsx</code>가 <code>onMessage</code>로 받아 브라우저 <code>Notification</code>을 띄우고, 클릭 시 같은 경로로 이동하며 <code>notification_clicked</code> 이벤트를 남깁니다.</li></ul><h2 id="question-selected" tabindex="-1">질문 선정 알림 (<code>question_selected</code>) <a class="header-anchor" href="#question-selected" aria-label="Permalink to &quot;질문 선정 알림 (`question_selected`) {#question-selected}&quot;">​</a></h2><p>제안한 질문을 운영자가 <strong>처음</strong> 선정하면 제안자에게 한 번 보냅니다. → <a href="/grato-docs/features/questions#after-approval">질문 제안과 선정</a></p><table tabindex="0"><thead><tr><th>항목</th><th>값</th></tr></thead><tbody><tr><td>보내는 곳</td><td><code>reviewQuestion</code> callable — 선정이 커밋된 뒤 (실패해도 선정은 취소되지 않음)</td></tr><tr><td>대상</td><td>사용자가 제안한 질문(<code>source: &quot;user&quot;</code>)의 제안자. 기본 질문은 보내지 않음</td></tr><tr><td>조건</td><td>선정 전에 <code>approvedAt</code>이 없던 질문(처음 선정)만. 숨겼다가 다시 선정해도 다시 보내지 않음</td></tr><tr><td>중복 방지</td><td><code>notificationLogs/question_selected_{questionId}</code></td></tr><tr><td>끄는 설정</td><td>없음 (자기 제안에 대한 결과 안내)</td></tr><tr><td>메시지</td><td>제목 &quot;제안한 질문이 선정됐어요 🎉&quot;, 본문 질문 문구, <code>data: { type: &quot;question_selected&quot;, questionId }</code></td></tr><tr><td>클릭 시</td><td><code>/mypage#questions</code></td></tr></tbody></table><ul><li><strong>백그라운드</strong>: 서비스 워커가 <code>/mypage#questions</code>로 이동합니다.</li><li><strong>포그라운드</strong>: <code>App.jsx</code>가 이미 MyPage에 있으면 &quot;내가 제안한 질문&quot; 카드로 스크롤만 하고, 아니면 <code>/mypage#questions</code>로 이동합니다.</li><li>MyPage의 <code>MyQuestionsSection</code>은 목록을 그린 뒤 주소의 해시가 <code>#questions</code>이면 그 카드로 스크롤합니다.</li><li>반려는 알림을 보내지 않습니다. 제안자는 MyPage에서 상태와 사유를 봅니다.</li></ul><h2 id="daily-reminder" tabindex="-1">매일 알림 (<code>sendDailyReminder</code>) <a class="header-anchor" href="#daily-reminder" aria-label="Permalink to &quot;매일 알림 (`sendDailyReminder`) {#daily-reminder}&quot;">​</a></h2><p>웹(과 앱이 로컬 알림을 맡지 않은 사용자)의 서버 발송입니다. 앱의 휴대폰 자체 알림은 <a href="#local-reminder">아래</a>에 있습니다.</p><table tabindex="0"><thead><tr><th>항목</th><th>값</th></tr></thead><tbody><tr><td>스케줄</td><td>15분마다 <code>*/15 * * * *</code>, 시간대 <code>Asia/Seoul</code> (예전 <code>every 1 hours</code>는 작업 생성 시각 기준이라 매시 40분에 돌았음)</td></tr><tr><td>대상 조회</td><td><code>dailyReminder == true</code>, <code>dailyReminderHour == 현재 KST 시</code>, 그리고 정각이 아니면 <code>dailyReminderMinute == 현재 15분 구간</code> (복합 인덱스). 정각 실행은 분 필드가 없는 예전 설정도 함께 처리</td></tr><tr><td>건너뛰기</td><td><code>userStats</code>로 확인해 <strong>오늘(KST) 이미 쓴 사용자</strong>. 그리고 앱이 로컬 알림을 맡은 사용자(<code>dailyReminderChannel == &#39;local&#39;</code>, <code>dailyReminderLocalAt</code>이 14일 안, <code>LOCAL_REMINDER_TTL_MS</code>) — 조회 뒤 메모리에서 거름(<code>reminderRecipients</code>), 로그에 <code>app-local</code> 수</td></tr><tr><td>처리 단위</td><td>100명씩 <code>userStats</code>를 한 번에 읽고 병렬 발송</td></tr><tr><td>중복 방지</td><td><code>daily_reminder_{uid}_{YYYYMMDD}_{HHMM}</code></td></tr><tr><td>제한</td><td>타임아웃 300초, 최대 인스턴스 3</td></tr></tbody></table><p>조회 조건에 시각을 넣어, 읽는 문서 수가 전체 사용자 수가 아니라 그 시각의 대상자 수에 비례합니다.</p><h2 id="app" tabindex="-1">앱 (iOS·Android) <a class="header-anchor" href="#app" aria-label="Permalink to &quot;앱 (iOS·Android) {#app}&quot;">​</a></h2><p>앱은 웹과 같은 알림 종류·설정·클릭 경로를 쓰고, 받는 방법만 네이티브입니다. 설정 절차(APNs 키, 채널)는 <a href="/grato-docs/mobile/#push">iOS·Android 앱</a>에 있습니다.</p><h3 id="푸시" tabindex="-1">푸시 <a class="header-anchor" href="#푸시" aria-label="Permalink to &quot;푸시&quot;">​</a></h3><table tabindex="0"><thead><tr><th>항목</th><th>앱에서</th></tr></thead><tbody><tr><td>플러그인</td><td><code>@capacitor-firebase/messaging</code> (<code>src/lib/native/push.js</code>, 앱에서만 불러옴)</td></tr><tr><td>토큰</td><td><code>pushTokens/{uid}/tokens/{token}</code> = <code>{token, platform: &#39;ios&#39; | &#39;android&#39;, createdAt}</code>. 권한이 이미 있을 때만 로그인 뒤 저장하고, 같은 토큰은 하루에 한 번까지 다시 씀. 토큰이 바뀌면(<code>tokenReceived</code>) 이 기기의 예전 문서를 지움</td></tr><tr><td>권한</td><td>OS 권한 하나가 푸시와 매일 알림을 함께 덮음. 홈 <code>PushPromptCard</code>(&quot;매일 감사 알림과 Circle 소식을 알려드려요&quot;), MyPage &quot;알림 켜기&quot;, MyPage에서 매일 알림을 켤 때만 요청. 자동으로 묻지 않음</td></tr><tr><td>거부했을 때</td><td>MyPage: &quot;알림이 꺼져 있어요 / 휴대폰 설정 › Grato › 알림에서 허용해 주세요&quot;. 설정에서 허용하고 돌아오면 토큰을 저장</td></tr><tr><td>백그라운드</td><td>OS가 <code>notification</code> 페이로드를 표시 → <a href="#message-shape">메시지 모양</a></td></tr><tr><td>포그라운드</td><td>iOS: OS가 배너·소리·배지로 표시. Android: 앱이 받아 같은 채널(<code>grato_push</code>)의 로컬 알림으로 표시</td></tr><tr><td>클릭</td><td>웹 서비스 워커와 같은 경로(<code>notifyHelpers.notificationPath</code>). 이미 MyPage면 질문 카드로 스크롤만. <code>notification_clicked</code> 이벤트에 <code>platform</code></td></tr><tr><td>로그아웃</td><td>토큰 문서와 FCM 토큰을 지움(남은 문서가 있어도 아무에게도 가지 않음)</td></tr></tbody></table><h3 id="local-reminder" tabindex="-1">매일 알림: 휴대폰 자체 알림 <a class="header-anchor" href="#local-reminder" aria-label="Permalink to &quot;매일 알림: 휴대폰 자체 알림 {#local-reminder}&quot;">​</a></h3><p>앱에서는 서버 푸시 대신 <code>@capacitor/local-notifications</code>로 휴대폰이 직접 띄웁니다(<code>src/lib/native/localReminders.js</code>). → <a href="/grato-docs/decisions#adr-16">결정 기록 #16</a></p><ul><li>시각은 웹과 같은 설정(KST, 15분 단위). 앞으로 14일 치를 하루씩 예약하고, 오늘 이미 썼거나 시각이 지났으면 오늘은 뺍니다.</li><li>앱 시작·복귀, 설정 변경, 글 저장, 권한 허용 때 다시 맞춥니다. MyPage 안내: &quot;매일 이 시간에 이 휴대폰으로 알려드려요. 기록한 날은 쉬어요 (15분 단위)&quot;.</li><li>Android 채널 <code>daily_reminder</code>(&quot;매일 감사 알림&quot;). 정확한 알람 권한은 쓰지 않아 절전 중에는 몇 분 늦을 수 있습니다.</li><li>예약하는 동안 <code>notificationSettings.dailyReminderChannel = &#39;local&#39;</code>과 <code>dailyReminderLocalAt</code>(서버 시각)을 한 번에 씁니다. 서버는 이 표시가 14일 안이면 그 사용자에게 매일 알림을 보내지 않습니다(웹 브라우저 포함, 하루 한 번만). 알림을 끄거나 권한이 없거나 로그아웃하면 <code>null</code>로 되돌려 서버 알림이 다시 갑니다. 앱을 지워 되돌리지 못해도 14일 뒤 만료됩니다.</li></ul>',25)),(d(),c(n,null,{default:e(()=>[r(o,{id:"mermaid-693",class:"mermaid",graph:"sequenceDiagram%0A%20%20participant%20A%20as%20%EC%95%B1%20(%ED%9C%B4%EB%8C%80%ED%8F%B0)%0A%20%20participant%20F%20as%20users%2F%7Buid%7D%0A%20%20participant%20S%20as%20sendDailyReminder%0A%20%20A-%3E%3EA%3A%2014%EC%9D%BC%20%EC%B9%98%20%EB%A1%9C%EC%BB%AC%20%EC%95%8C%EB%A6%BC%20%EC%98%88%EC%95%BD%20(%EC%98%A4%EB%8A%98%20%EC%8D%BC%EC%9C%BC%EB%A9%B4%20%EB%82%B4%EC%9D%BC%EB%B6%80%ED%84%B0)%0A%20%20A-%3E%3EF%3A%20dailyReminderChannel%20%3D%20'local'%2C%20dailyReminderLocalAt%20%3D%20%EC%84%9C%EB%B2%84%20%EC%8B%9C%EA%B0%81%20(%ED%95%98%EB%A3%A8%20%ED%95%9C%20%EB%B2%88%EA%B9%8C%EC%A7%80)%0A%20%20S-%3E%3EF%3A%20%EA%B7%B8%20%EC%8B%9C%EA%B0%81%20%EB%8C%80%EC%83%81%20%EC%A1%B0%ED%9A%8C%0A%20%20S--%3E%3ES%3A%20'local'%EC%9D%B4%EA%B3%A0%2014%EC%9D%BC%20%EC%95%88%EC%9D%B4%EB%A9%B4%20%EA%B1%B4%EB%84%88%EB%9C%80%0A%20%20Note%20over%20A%3A%20%EC%A0%95%ED%95%9C%20%EC%8B%9C%EA%B0%81%EC%97%90%20%ED%9C%B4%EB%8C%80%ED%8F%B0%EC%9D%B4%20%EC%A7%81%EC%A0%91%20%EC%95%8C%EB%A6%BC%20%E2%86%92%20%EB%88%84%EB%A5%B4%EB%A9%B4%20%2Fwrite%0A"})]),fallback:e(()=>[...t[1]||(t[1]=[i(" Loading... ",-1)])]),_:1}))])}const q=s(E,[["render",h]]);export{b as __pageData,q as default};
